with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , SPECIAL_REMARKS as PROVIDER_REMARKS
        , cast(null as varchar) as DOCTOR_TO_PATIENT_RATIO
        , cast(null as varchar) as BED_OCCUPANCY_RATE
        , cast(null as varchar) as DOCTOR_TO_BED_RATIO
        , cast(null as varchar) as NURSE_TO_BED_RATIO
        , cast(null as varchar) as NURSE_TO_PATIENT_RATIO
        , cast(null as varchar) as AVERAGE_ADMISSION_TIME
        , cast(null as varchar) as AVERAGE_LENGTH_OF_STAY_MEDICAL
        , cast(null as varchar) as AVERAGE_DISCHARGE_TIME
        , cast(null as varchar) as AVERAGE_LENGTH_OF_STAY_SURGICAL
        , cast(null as varchar) as CAESAREAN_SECTION_RATE
        , cast(null as varchar) as PROVIDER_CONFIGURED_DATE
        , cast(null as varchar) as PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE
        , cast(null as varchar) as PROVIDER_RECORD_FLAG
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as PROVIDER_REMARKS
        , DOCT_PATNT_RATIO as DOCTOR_TO_PATIENT_RATIO
        , BEDOCCUPRATE as BED_OCCUPANCY_RATE
        , DOCT_BED_RATIO as DOCTOR_TO_BED_RATIO
        , NURSE_BED_RATIO as NURSE_TO_BED_RATIO
        , NURSE_PTNT_RATIO as NURSE_TO_PATIENT_RATIO
        , AVG_ADMSION_TIME as AVERAGE_ADMISSION_TIME
        , AVG_STY_MEDI_CASE as AVERAGE_LENGTH_OF_STAY_MEDICAL
        , AVG_DSCRG_TIME as AVERAGE_DISCHARGE_TIME
        , AVG_STY_SURGCL_CASE as AVERAGE_LENGTH_OF_STAY_SURGICAL
        , C_SECTION_RATE as CAESAREAN_SECTION_RATE
        , cast(null as varchar) as PROVIDER_CONFIGURED_DATE
        , cast(null as varchar) as PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE
        , cast(null as varchar) as PROVIDER_RECORD_FLAG
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CONTRACT_ID_INSURED_NAME))) as HUB_PARTY_HK
        , cast(null as varchar) as PROVIDER_REMARKS
        , cast(null as varchar) as DOCTOR_TO_PATIENT_RATIO
        , cast(null as varchar) as BED_OCCUPANCY_RATE
        , cast(null as varchar) as DOCTOR_TO_BED_RATIO
        , cast(null as varchar) as NURSE_TO_BED_RATIO
        , cast(null as varchar) as NURSE_TO_PATIENT_RATIO
        , cast(null as varchar) as AVERAGE_ADMISSION_TIME
        , cast(null as varchar) as AVERAGE_LENGTH_OF_STAY_MEDICAL
        , cast(null as varchar) as AVERAGE_DISCHARGE_TIME
        , cast(null as varchar) as AVERAGE_LENGTH_OF_STAY_SURGICAL
        , cast(null as varchar) as CAESAREAN_SECTION_RATE
        , CONFIGURED_DATE as PROVIDER_CONFIGURED_DATE
        , UPDATED_BY as PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE
        , FLAG as PROVIDER_RECORD_FLAG
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROVIDER_REMARKS end) as PROVIDER_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCTOR_TO_PATIENT_RATIO end) as DOCTOR_TO_PATIENT_RATIO,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BED_OCCUPANCY_RATE end) as BED_OCCUPANCY_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCTOR_TO_BED_RATIO end) as DOCTOR_TO_BED_RATIO,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NURSE_TO_BED_RATIO end) as NURSE_TO_BED_RATIO,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NURSE_TO_PATIENT_RATIO end) as NURSE_TO_PATIENT_RATIO,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AVERAGE_ADMISSION_TIME end) as AVERAGE_ADMISSION_TIME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AVERAGE_LENGTH_OF_STAY_MEDICAL end) as AVERAGE_LENGTH_OF_STAY_MEDICAL,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AVERAGE_DISCHARGE_TIME end) as AVERAGE_DISCHARGE_TIME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AVERAGE_LENGTH_OF_STAY_SURGICAL end) as AVERAGE_LENGTH_OF_STAY_SURGICAL,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CAESAREAN_SECTION_RATE end) as CAESAREAN_SECTION_RATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PROVIDER_CONFIGURED_DATE end) as PROVIDER_CONFIGURED_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE end) as PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PROVIDER_RECORD_FLAG end) as PROVIDER_RECORD_FLAG,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when PROVIDER_REMARKS is not null or DOCTOR_TO_PATIENT_RATIO is not null or BED_OCCUPANCY_RATE is not null or DOCTOR_TO_BED_RATIO is not null or NURSE_TO_BED_RATIO is not null or NURSE_TO_PATIENT_RATIO is not null or AVERAGE_ADMISSION_TIME is not null or AVERAGE_LENGTH_OF_STAY_MEDICAL is not null or AVERAGE_DISCHARGE_TIME is not null or AVERAGE_LENGTH_OF_STAY_SURGICAL is not null or CAESAREAN_SECTION_RATE is not null or PROVIDER_CONFIGURED_DATE is not null or PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE is not null or PROVIDER_RECORD_FLAG is not null
                     then md5(upper(coalesce(cast(PROVIDER_REMARKS as varchar), '') || '|' || coalesce(cast(DOCTOR_TO_PATIENT_RATIO as varchar), '') || '|' || coalesce(cast(BED_OCCUPANCY_RATE as varchar), '') || '|' || coalesce(cast(DOCTOR_TO_BED_RATIO as varchar), '') || '|' || coalesce(cast(NURSE_TO_BED_RATIO as varchar), '') || '|' || coalesce(cast(NURSE_TO_PATIENT_RATIO as varchar), '') || '|' || coalesce(cast(AVERAGE_ADMISSION_TIME as varchar), '') || '|' || coalesce(cast(AVERAGE_LENGTH_OF_STAY_MEDICAL as varchar), '') || '|' || coalesce(cast(AVERAGE_DISCHARGE_TIME as varchar), '') || '|' || coalesce(cast(AVERAGE_LENGTH_OF_STAY_SURGICAL as varchar), '') || '|' || coalesce(cast(CAESAREAN_SECTION_RATE as varchar), '') || '|' || coalesce(cast(PROVIDER_CONFIGURED_DATE as varchar), '') || '|' || coalesce(cast(PROVIDER_RECORD_LAST_UPDATED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(PROVIDER_RECORD_FLAG as varchar), '')))
                end as SAT_PROVIDER_QUALITY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PROVIDER_QUALITY_HASHDIFF is not null
